// (1) ROUTES: an array of path -> component.
const routes: Routes = [
  { path: 'home', component: HomeComponent },
  { path: 'users/:id', component: UserDetailComponent },  // param route
  { path: '', redirectTo: 'home', pathMatch: 'full' },     // default
];
@NgModule({ imports: [RouterModule.forRoot(routes)] })
export class AppRoutingModule {}

// (2) ROUTER-OUTLET: where the matched component renders.
//   <router-outlet></router-outlet>   <- in the host template

// (3) ROUTERLINK: declarative links (NO full reload, unlike href).
//   <a routerLink="/home">Home</a>
//   <a [routerLink]="['/users', user.id]">User</a>   // param link

// (4) READ PARAMS in the component via ActivatedRoute.
export class UserDetailComponent {
  constructor(private route: ActivatedRoute) {}
  ngOnInit() { this.route.paramMap.subscribe(p => this.id = p.get('id')); }
}
